-- 020_identity_verification: private identity facts and durable provider/binding state.
-- @step learner_identity
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='learner_identity' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='learner_identity')=7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='learner_identity' AND ((COLUMN_NAME='id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='auto_increment') OR (COLUMN_NAME='user_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='id_fingerprint' AND COLUMN_TYPE='char(64)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='identity_encrypted' AND COLUMN_TYPE='text' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='session_id' AND COLUMN_TYPE='char(36)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='provider_request_id' AND COLUMN_TYPE='varchar(128)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='verified_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED')))=7 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='learner_identity')=4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='learner_identity' AND ((INDEX_NAME='PRIMARY' AND COLUMN_NAME='id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=0 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='uk_learner_identity_user' AND COLUMN_NAME='user_id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=0 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='uk_learner_identity_fingerprint' AND COLUMN_NAME='id_fingerprint' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=0 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='uk_learner_identity_session' AND COLUMN_NAME='session_id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=0 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES')))=4 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS learner_identity (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id BIGINT UNSIGNED NOT NULL,
  id_fingerprint CHAR(64) NOT NULL,
  identity_encrypted TEXT NOT NULL,
  session_id CHAR(36) NOT NULL,
  provider_request_id VARCHAR(128) NOT NULL,
  verified_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uk_learner_identity_user (user_id),
  UNIQUE KEY uk_learner_identity_fingerprint (id_fingerprint),
  UNIQUE KEY uk_learner_identity_session (session_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- @step identity_verification_session
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='identity_verification_session' AND TABLE_TYPE='BASE TABLE' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='identity_verification_session')=17 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='identity_verification_session' AND ((COLUMN_NAME='id' AND COLUMN_TYPE='char(36)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='user_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='face_asset_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='id_card_portrait_asset_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='id_card_emblem_asset_id' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='material_fingerprint' AND COLUMN_TYPE='char(64)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='status' AND COLUMN_TYPE='varchar(24)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='provider' AND COLUMN_TYPE='varchar(32)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='provider_request_id' AND COLUMN_TYPE='varchar(128)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='provider_result_encrypted' AND COLUMN_TYPE='text' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='provider_lease_until' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='reason_code' AND COLUMN_TYPE='varchar(64)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='expires_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='bound_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='') OR (COLUMN_NAME='bound_event_id' AND COLUMN_TYPE='char(36)' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci') OR (COLUMN_NAME='created_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED') OR (COLUMN_NAME='updated_at' AND COLUMN_TYPE='datetime(3)' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='CURRENT_TIMESTAMP(3)' AND EXTRA='DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)')))=17 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='identity_verification_session')=6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='identity_verification_session' AND ((INDEX_NAME='PRIMARY' AND COLUMN_NAME='id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=0 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='idx_identity_session_user_created' AND COLUMN_NAME='user_id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=1 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='idx_identity_session_user_created' AND COLUMN_NAME='created_at' AND SEQ_IN_INDEX=2 AND NON_UNIQUE=1 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='idx_identity_session_material' AND COLUMN_NAME='user_id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=1 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='idx_identity_session_material' AND COLUMN_NAME='material_fingerprint' AND SEQ_IN_INDEX=2 AND NON_UNIQUE=1 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES') OR (INDEX_NAME='uk_identity_session_bound_event' AND COLUMN_NAME='bound_event_id' AND SEQ_IN_INDEX=1 AND NON_UNIQUE=0 AND INDEX_TYPE='BTREE' AND SUB_PART IS NULL AND IS_VISIBLE='YES')))=6 THEN 1 ELSE 0 END AS complete;
CREATE TABLE IF NOT EXISTS identity_verification_session (
  id CHAR(36) NOT NULL,
  user_id BIGINT UNSIGNED NOT NULL,
  face_asset_id BIGINT UNSIGNED NOT NULL,
  id_card_portrait_asset_id BIGINT UNSIGNED NOT NULL,
  id_card_emblem_asset_id BIGINT UNSIGNED NOT NULL,
  material_fingerprint CHAR(64) NOT NULL,
  status VARCHAR(24) NOT NULL,
  provider VARCHAR(32) NOT NULL,
  provider_request_id VARCHAR(128) NULL,
  provider_result_encrypted TEXT NULL,
  provider_lease_until DATETIME(3) NULL,
  reason_code VARCHAR(64) NULL,
  expires_at DATETIME(3) NOT NULL,
  bound_at DATETIME(3) NULL,
  bound_event_id CHAR(36) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_identity_session_user_created (user_id,created_at),
  KEY idx_identity_session_material (user_id,material_fingerprint),
  UNIQUE KEY uk_identity_session_bound_event (bound_event_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
